<script setup>
import { computed } from 'vue';
const props=defineProps({rows:{type:Array,default:()=>[]},year:{type:Number,required:true}});
const emit=defineEmits(['filter']);
const approvedStates=['approved','realizing','completed'];
const colors=['#4b83da','#32a98b','#eeb550','#7e6dcc','#e25964','#42b7bf','#7891ab'];
const statusLabels={draft:'Draft',submitted:'Diajukan',reviewed:'Ditinjau',approved:'Disetujui',rejected:'Ditolak',realizing:'Realisasi',completed:'Selesai'};
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const percent=(value,total)=>total?Math.round(value/total*100):0;
const sum=(items,key)=>items.reduce((n,r)=>n+Number(r[key]||0),0);
const total=computed(()=>sum(props.rows,'amount'));
const approved=computed(()=>sum(props.rows.filter(r=>approvedStates.includes(r.status)),'amount'));
const actual=computed(()=>sum(props.rows,'actual'));
const waiting=computed(()=>props.rows.filter(r=>['submitted','reviewed'].includes(r.status)));
const types=computed(()=>['CAPEX','OPEX'].map((label,i)=>{const items=props.rows.filter(r=>r.type===label);return {label,value:sum(items,'amount'),approved:sum(items.filter(r=>approvedStates.includes(r.status)),'amount'),actual:sum(items,'actual'),count:items.length,color:colors[i]};}));
const statuses=computed(()=>Object.entries(statusLabels).map(([key,label],i)=>({key,label,value:props.rows.filter(r=>r.status===key).length,color:colors[i]})));
function slices(items){let offset=0;const total=items.reduce((n,r)=>n+r.value,0);return items.filter(r=>r.value>0).map(r=>{const share=total?r.value/total*100:0;const item={...r,share,offset};offset+=share;return item;});}
const typeSlices=computed(()=>slices(types.value)),statusSlices=computed(()=>slices(statuses.value));
const maxComparison=computed(()=>Math.max(1,...types.value.map(r=>r.value)));
const departments=computed(()=>{const groups=new Map();for(const r of props.rows){const name=r.department||'Tanpa bagian';if(!groups.has(name))groups.set(name,{name,value:0,actual:0,count:0});const d=groups.get(name);d.value+=Number(r.amount||0);d.actual+=Number(r.actual||0);d.count++;}return [...groups.values()].sort((a,b)=>b.value-a.value||a.name.localeCompare(b.name));});
const topDepartments=computed(()=>departments.value.slice(0,8));
const maxDepartment=computed(()=>Math.max(1,...topDepartments.value.map(d=>d.value)));
</script>

<template>
  <div class="budget-analytics">
    <div class="section-heading"><div><p class="eyebrow">DASHBOARD ANGGARAN</p><h3>Ringkasan tahun {{year}}</h3><p class="muted">Seluruh pengajuan tahun terpilih. Klik legenda atau bagian untuk membuka daftar terkait.</p></div></div>
    <div class="ba-kpis">
      <article class="insight-panel"><span>Total pengajuan</span><strong>{{money(total)}}</strong><small>{{rows.length}} pengajuan CAPEX dan OPEX</small></article>
      <article class="insight-panel"><span>Anggaran disetujui</span><strong>{{money(approved)}}</strong><small>Termasuk yang sedang direalisasi dan selesai</small></article>
      <article class="insight-panel"><span>Penyerapan anggaran</span><strong>{{percent(actual,approved)}}%</strong><progress :value="actual" :max="approved||1" aria-label="Penyerapan anggaran disetujui"></progress><small>{{money(actual)}} dari {{money(approved)}}</small></article>
      <button class="insight-panel ba-kpi-button" @click="emit('filter',{pending:true})"><span>Menunggu review / persetujuan</span><strong>{{waiting.length}} pengajuan</strong><small>{{money(sum(waiting,'amount'))}}</small></button>
    </div>
    <div class="ba-grid">
      <article class="insight-panel ba-panel"><h3>Komposisi CAPEX dan OPEX</h3><p class="muted">Berdasarkan nominal seluruh pengajuan.</p><div class="ba-donut-layout"><svg viewBox="0 0 160 160" class="ba-donut" role="img" :aria-label="'Komposisi CAPEX dan OPEX tahun '+year"><circle cx="80" cy="80" r="58" fill="none" stroke="var(--line)" stroke-width="19"/><circle v-for="s in typeSlices" :key="s.label" cx="80" cy="80" r="58" fill="none" :stroke="s.color" stroke-width="19" pathLength="100" :stroke-dasharray="`${s.share} ${100-s.share}`" :stroke-dashoffset="-s.offset" transform="rotate(-90 80 80)"><title>{{s.label}}: {{money(s.value)}} ({{Math.round(s.share)}}%)</title></circle><text x="80" y="77" text-anchor="middle" class="ba-ring-number">{{rows.length}}</text><text x="80" y="98" text-anchor="middle" class="ba-ring-label">pengajuan</text></svg><div class="ba-legend"><button v-for="t in types" :key="t.label" @click="emit('filter',{type:t.label})"><span class="ba-dot" :style="{background:t.color}"></span><span>{{t.label}}<small>{{t.count}} pengajuan · {{percent(t.value,total)}}%</small></span><strong>{{money(t.value)}}</strong></button></div></div><p v-if="!total" class="muted">Belum ada nominal pengajuan pada tahun ini.</p></article>
      <article class="insight-panel ba-panel"><h3>Distribusi status pengajuan</h3><p class="muted">Berdasarkan jumlah pengajuan pada status saat ini.</p><div class="ba-donut-layout"><svg viewBox="0 0 160 160" class="ba-donut" role="img" aria-label="Distribusi jumlah pengajuan per status"><circle cx="80" cy="80" r="58" fill="none" stroke="var(--line)" stroke-width="19"/><circle v-for="s in statusSlices" :key="s.key" cx="80" cy="80" r="58" fill="none" :stroke="s.color" stroke-width="19" pathLength="100" :stroke-dasharray="`${s.share} ${100-s.share}`" :stroke-dashoffset="-s.offset" transform="rotate(-90 80 80)"><title>{{s.label}}: {{s.value}} pengajuan ({{Math.round(s.share)}}%)</title></circle><text x="80" y="86" text-anchor="middle" class="ba-ring-number">{{rows.length}}</text></svg><div class="ba-legend"><button v-for="s in statuses" :key="s.key" @click="emit('filter',{status:s.key})"><span class="ba-dot" :style="{background:s.color}"></span><span>{{s.label}}</span><strong>{{s.value}}</strong></button></div></div><p v-if="!rows.length" class="muted">Belum ada pengajuan pada tahun ini.</p></article>
      <article class="insight-panel ba-panel"><h3>Pengajuan, persetujuan & realisasi</h3><p class="muted">Nominal IDR pada skala yang sama untuk kedua jenis.</p><div class="ba-series-legend"><span><i style="background:#4b83da"></i>Pengajuan</span><span><i style="background:#32a98b"></i>Disetujui</span><span><i style="background:#eeb550"></i>Realisasi</span></div><div v-for="t in types" :key="t.label" class="ba-bar-group"><strong>{{t.label}}</strong><div v-for="metric in [{key:'value',label:'Pengajuan',color:'#4b83da'},{key:'approved',label:'Disetujui',color:'#32a98b'},{key:'actual',label:'Realisasi',color:'#eeb550'}]" :key="metric.key" class="ba-bar-row"><span>{{metric.label}}</span><div class="ba-track" role="img" :aria-label="t.label+' '+metric.label+': '+money(t[metric.key])"><span :style="{width:(t[metric.key]/maxComparison*100)+'%',background:metric.color}"></span></div><strong>{{money(t[metric.key])}}</strong></div></div><p class="muted">Realisasi dicatat saat proses diselesaikan. Sisa disetujui: <strong>{{money(approved-actual)}}</strong>.</p></article>
      <article class="insight-panel ba-panel"><h3>Bagian dengan pengajuan terbesar</h3><p class="muted">Maksimal 8 bagian, diurutkan berdasarkan nominal pengajuan.</p><button v-for="d in topDepartments" :key="d.name" class="ba-department" @click="emit('filter',{department:d.name})"><span><strong>{{d.name}}</strong><strong>{{money(d.value)}}</strong></span><div class="ba-track"><span :style="{width:d.value/maxDepartment*100+'%',background:'#4b83da'}"></span></div><small>{{d.count}} pengajuan · Realisasi {{money(d.actual)}}</small></button><p v-if="!departments.length" class="muted">Belum ada data bagian pengaju.</p><small v-if="departments.length>8" class="muted">{{departments.length-8}} bagian lainnya tersedia pada rekap bagian di bawah.</small></article>
    </div>
  </div>
</template>

<style scoped>
.budget-analytics{margin-top:24px}.ba-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:20px}.ba-kpis>article,.ba-kpi-button{display:flex;flex-direction:column;gap:12px;margin:0;min-width:0;padding:20px}.ba-kpis strong{font-size:22px;overflow-wrap:anywhere;color:var(--navy)}.ba-kpis span,.ba-kpis small{color:var(--muted);font-size:12px}.ba-kpi-button{font:inherit;text-align:left;cursor:pointer;color:inherit;background:var(--surface,#fff);border:1px solid var(--line);border-radius:12px}.ba-kpis progress{width:100%;height:8px;accent-color:#32a98b}.ba-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.ba-panel{margin:0;min-width:0;padding:22px}.ba-panel h3{margin:0 0 8px}.ba-panel .muted{font-size:12px;line-height:1.6}.ba-donut-layout{display:flex;align-items:center;gap:20px;margin-top:18px}.ba-donut{width:150px;height:150px;flex:0 0 150px}.ba-ring-number{font-size:28px;font-weight:700;fill:var(--navy)}.ba-ring-label{font-size:12px;fill:var(--muted)}.ba-legend{flex:1;min-width:0}.ba-legend button{display:flex;align-items:center;gap:8px;width:100%;padding:10px 0;border:0;border-bottom:1px solid var(--line);background:transparent;font:inherit;color:inherit;text-align:left;cursor:pointer;font-size:12px}.ba-legend button>strong{margin-left:auto;text-align:right;overflow-wrap:anywhere}.ba-legend small{display:block;color:var(--muted);margin-top:4px}.ba-dot,.ba-series-legend i{height:9px;width:9px;border-radius:50%;flex-shrink:0;display:inline-block}.ba-series-legend{display:flex;gap:14px;flex-wrap:wrap;font-size:11px;margin:18px 0}.ba-series-legend span{display:flex;gap:6px;align-items:center}.ba-bar-group{margin:20px 0}.ba-bar-row{display:grid;grid-template-columns:70px minmax(30px,1fr) minmax(90px,auto);gap:10px;align-items:center;font-size:11px;margin:12px 0}.ba-bar-row>strong{text-align:right;font-variant-numeric:tabular-nums}.ba-track{height:9px;background:var(--line);border-radius:5px;overflow:hidden}.ba-track>span{display:block;height:100%;border-radius:5px}.ba-department{display:block;width:100%;background:transparent;border:0;border-bottom:1px solid var(--line);padding:14px 0;text-align:left;font:inherit;color:inherit;cursor:pointer}.ba-department>span{display:flex;justify-content:space-between;gap:12px;font-size:12px;margin-bottom:8px;overflow-wrap:anywhere}.ba-department small{display:block;color:var(--muted);font-size:11px;margin-top:7px}.ba-legend button:hover,.ba-department:hover{color:var(--green)}button:focus-visible{outline:2px solid var(--green);outline-offset:3px}@media(max-width:1100px){.ba-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.ba-donut-layout{flex-direction:column}.ba-legend{width:100%}}@media(max-width:700px){.ba-grid,.ba-kpis{grid-template-columns:1fr}.ba-bar-row{grid-template-columns:65px minmax(20px,1fr);gap:7px}.ba-bar-row>strong{grid-column:2}.ba-panel{padding:16px}}
</style>
